import{_ as t,o as n,c as s,a4 as a}from"./chunks/framework.BE47AOxC.js";const m=JSON.parse(`{"title":"ADR-0032 — Droits du déposant sans compte : l'accès par le jeton, l'effacement tranché par le service","description":"Extrait de docs/adr/0032-droits-du-deposant-sans-compte.md, publié tel quel à chaque construction du site.","frontmatter":{"title":"ADR-0032 — Droits du déposant sans compte : l'accès par le jeton, l'effacement tranché par le service","description":"Extrait de docs/adr/0032-droits-du-deposant-sans-compte.md, publié tel quel à chaque construction du site."},"headers":[],"relativePath":"developpeurs/adr/0032-droits-du-deposant-sans-compte.md","filePath":"developpeurs/adr/0032-droits-du-deposant-sans-compte.md"}`),r={name:"developpeurs/adr/0032-droits-du-deposant-sans-compte.md"};function o(i,e,d,l,c,u){return n(),s("div",null,[...e[0]||(e[0]=[a('<h1 id="adr-0032--droits-du-déposant-sans-compte--laccès-par-le-jeton-leffacement-tranché-par-le-service" tabindex="-1">ADR-0032 — Droits du déposant sans compte : l&#39;accès par le jeton, l&#39;effacement tranché par le service <a class="header-anchor" href="#adr-0032--droits-du-déposant-sans-compte--laccès-par-le-jeton-leffacement-tranché-par-le-service" aria-label="Permalink to &quot;ADR-0032 — Droits du déposant sans compte : l&#39;accès par le jeton, l&#39;effacement tranché par le service {#adr-0032--droits-du-déposant-sans-compte--laccès-par-le-jeton-leffacement-tranché-par-le-service}&quot;">​</a></h1><p><strong>Date :</strong> 17 septembre 2026 <strong>Statut :</strong> Accepté <strong>Décideur :</strong> Sébastien Rapuzzi (Product Owner) <strong>Source :</strong> audit de sécurité et RGPD du 15 septembre 2026 (constat 9.2) ; RGPD art. 12 §3 et §4, 15 §3, 17 §1 et §3 ; Code du patrimoine, art. L212-2 et L212-3 ; CDC_CMS_AI_Native_v1.1 §7.3 et §13.1 ; prolonge l&#39;<a href="/teuthis-cms-distribution/developpeurs/adr/0030-conservation-des-donnees-anonymisation">ADR-0030</a> et l&#39;<a href="/teuthis-cms-distribution/developpeurs/adr/0031-limitation-de-debit">ADR-0031</a></p><h2 id="contexte" tabindex="-1">Contexte <a class="header-anchor" href="#contexte" aria-label="Permalink to &quot;Contexte {#contexte}&quot;">​</a></h2><p>Un guichet public se pratique surtout <strong>sans compte</strong>. On dépose une demande, on reçoit un numéro de dossier et un lien de suivi, et c&#39;est tout. Avec ce numéro et ce jeton, le déposant pouvait lire son dossier, y répondre et annuler sa demande. Il ne pouvait <strong>ni obtenir une copie de ses données</strong>, ni <strong>en demander l&#39;effacement</strong>.</p><p>Un usager qui a un compte dispose des deux droits depuis son espace personnel : un export complet et la suppression de son compte. Un déposant sans compte devait écrire au délégué à la protection des données, qui devait ensuite intervenir directement en base. Ce sont pourtant les mêmes données, déposées par le même formulaire.</p><p>Les deux droits n&#39;appellent pas la même réponse.</p><ul><li><strong>L&#39;accès ne retire rien.</strong> Le jeton donne déjà à l&#39;écran tout ce que l&#39;archive contiendrait. Le rendre téléchargeable ne crée aucun nouveau pouvoir, seulement une copie.</li><li><strong>L&#39;effacement détruit.</strong> L&#39;article 17 §3 en écarte l&#39;application quand le traitement est nécessaire à une mission de service public, au respect d&#39;une obligation légale ou à l&#39;archivage dans l&#39;intérêt public. Pour une collectivité, une saisine est une archive publique, et sa destruction relève du visa du service d&#39;archives (ADR-0030). Le logiciel ne peut pas savoir si ces exceptions s&#39;appliquent à un dossier donné : c&#39;est au responsable de traitement d&#39;en juger.</li></ul><h2 id="décision" tabindex="-1">Décision <a class="header-anchor" href="#décision" aria-label="Permalink to &quot;Décision {#décision}&quot;">​</a></h2><p><strong>Le déposant télécharge lui-même la copie de ses données. Sa demande d&#39;effacement est une requête que le service tranche, dans le délai légal, et dont il reçoit la réponse motivée.</strong></p><h3 id="1-laccès-tout-de-suite" tabindex="-1">1. L&#39;accès, tout de suite <a class="header-anchor" href="#1-laccès-tout-de-suite" aria-label="Permalink to &quot;1. L&#39;accès, tout de suite {#1-laccès-tout-de-suite}&quot;">​</a></h3><p>Depuis le suivi, avec le numéro de dossier, le jeton et le captcha, le déposant télécharge une archive ZIP de son dossier :</p><ul><li>le contenu de ce qu&#39;il a déposé ;</li><li>les messages du fil, sans les notes internes du service ;</li><li>ses fichiers ;</li><li>les consultations de son dossier par les agents.</li></ul><p>L&#39;archive a le <strong>même format</strong> que l&#39;export d&#39;un compte, et elle est construite par les mêmes fonctions. Elle est rendue dans la réponse : aucune copie n&#39;est conservée sur le serveur. Le téléchargement est inscrit au journal d&#39;accès, sans aucune donnée. La limite de débit des accès par jeton (ADR-0031) s&#39;applique.</p><h3 id="2-leffacement-une-demande" tabindex="-1">2. L&#39;effacement, une demande <a class="header-anchor" href="#2-leffacement-une-demande" aria-label="Permalink to &quot;2. L&#39;effacement, une demande {#2-leffacement-une-demande}&quot;">​</a></h3><p>Le déposant dépose une demande d&#39;effacement, protégée par le jeton et le captcha. Elle reçoit une <strong>échéance d&#39;un mois civil</strong> (art. 12 §3), un accusé de réception part au déposant, et une alerte part aux agents chargés du RGPD. Une seconde demande sur le même dossier renvoie la première au lieu d&#39;en créer une autre.</p><p>Un agent qui porte la permission <code>rgpd.manage</code> la tranche depuis un écran dédié, qui signale les demandes en retard.</p><ul><li><strong>S&#39;il accepte</strong>, le dossier est anonymisé <strong>immédiatement</strong>, par la même fonction que l&#39;anonymisation à échéance (ADR-0030), avec les mêmes effets et le même garde-fou. <ul><li>Le courriel d&#39;acceptation part <strong>avant</strong> l&#39;anonymisation, puisque celle-ci efface l&#39;adresse et le jeton de suivi : ce courriel est la dernière chose que le déposant reçoit à propos de ce dossier.</li><li>Si le garde-fou refuse (un type de contenu marqué personnel dont aucun champ ne l&#39;est), l&#39;acceptation est refusée et rien ne change.</li></ul></li><li><strong>S&#39;il refuse</strong>, il doit donner un <strong>motif</strong>, qui part au déposant avec la mention de son droit de saisir la CNIL (art. 12 §4). Le dossier reste intact.</li></ul><p>Une demande déjà tranchée ne peut plus l&#39;être à nouveau.</p><h2 id="alternatives-considérées" tabindex="-1">Alternatives considérées <a class="header-anchor" href="#alternatives-considérées" aria-label="Permalink to &quot;Alternatives considérées {#alternatives-considérées}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Option</th><th>Pourquoi écartée</th></tr></thead><tbody><tr><td><strong>Anonymisation immédiate au clic du déposant</strong></td><td>Le CMS détruirait seul une archive publique, et un dossier en cours d&#39;instruction perdrait ses pièces à l&#39;insu du service. C&#39;est ce que l&#39;ADR-0030 a écarté.</td></tr><tr><td><strong>Anonymisation immédiate si la demande est annulée, requête sinon</strong></td><td>Deux règles à expliquer, pour un gain faible : une demande annulée reste une archive.</td></tr><tr><td><strong>Archive d&#39;accès envoyée par courriel</strong></td><td>Une pièce jointe de données personnelles par courriel est un risque en soi, et une demande déposée sans adresse n&#39;aurait pas d&#39;accès. Le jeton suffit déjà à tout lire à l&#39;écran.</td></tr><tr><td><strong>Archive d&#39;accès déposée comme fichier personnel, puis téléchargée</strong></td><td>C&#39;est ce que fait l&#39;export d&#39;un compte, qui a une session pour y revenir. Le porteur d&#39;un jeton n&#39;en a pas, et une copie conservée serait une copie de plus à purger.</td></tr><tr><td><strong>Laisser ces demandes au courrier du DPO</strong></td><td>La situation d&#39;avant : un droit qui ne s&#39;exerce que par une intervention en base, sans échéance visible.</td></tr></tbody></table><h2 id="conséquences" tabindex="-1">Conséquences <a class="header-anchor" href="#conséquences" aria-label="Permalink to &quot;Conséquences {#conséquences}&quot;">​</a></h2><p><strong>Positives</strong></p><ul><li>Le déposant sans compte exerce ses droits d&#39;accès et d&#39;effacement sans rien demander à personne pour le premier, et avec une réponse datée et motivée pour le second.</li><li>Le service voit ses demandes d&#39;effacement et leur échéance au lieu de les découvrir dans une boîte aux lettres.</li><li>Il n&#39;existe toujours qu&#39;un seul geste d&#39;anonymisation dans le Core.</li></ul><p><strong>Négatives, et il y en a</strong></p><ul><li><strong>Un jeton fuité donne la copie du dossier.</strong> C&#39;était déjà vrai à l&#39;écran. Le captcha et la limite de débit empêchent seulement l&#39;exploitation en masse.</li><li><strong>Le délai d&#39;un mois n&#39;est pas contraignant</strong> : le CMS le signale, il ne l&#39;impose pas. La prolongation de deux mois (art. 12 §3) n&#39;est pas gérée ; l&#39;agent la motive dans le fil de discussion.</li><li><strong>Après acceptation, le déposant n&#39;a plus accès à son dossier</strong> : le jeton est effacé avec le reste. Le courriel d&#39;acceptation est sa seule preuve. S&#39;il n&#39;a pas pu partir, la décision est tout de même appliquée, et l&#39;agent en est averti.</li><li><strong>La rectification</strong> (art. 16) n&#39;a pas de route dédiée : le déposant la demande dans le fil de discussion.</li><li><strong>Ce dépôt n&#39;a pas de front-office</strong> : les routes publiques sont prêtes, et chaque site doit les présenter.</li></ul>',25)])])}const g=t(r,[["render",o]]);export{m as __pageData,g as default};
